-- Independent ODbL public map catalogue; not formal logistics samples or operational capacity.
CREATE TABLE overview.regional_railway_feature (
    source_id text PRIMARY KEY CHECK (source_id ~ '^(node|way)/[0-9]+$'),
    name text NOT NULL,
    kind text NOT NULL CHECK (kind IN ('station','halt','yard','rail')),
    tags jsonb NOT NULL,
    geometry geometry(Geometry,4326) NOT NULL,
    source_as_of timestamptz NOT NULL,
    CHECK (ST_IsValid(geometry) AND NOT ST_IsEmpty(geometry)),
    CHECK (GeometryType(geometry) IN ('POINT','LINESTRING'))
);
CREATE INDEX regional_railway_feature_geometry_gix ON overview.regional_railway_feature USING gist(geometry);
CREATE INDEX regional_railway_feature_geography_gix ON overview.regional_railway_feature USING gist((geometry::geography));
GRANT SELECT ON overview.regional_railway_feature TO qiqihar_enterprise_runtime;
COMMENT ON TABLE overview.regional_railway_feature IS 'OpenStreetMap contributors, ODbL-1.0. Public geographical reference only. Source snapshot and downloadable dataset retained.';

