INSERT INTO overview.regional_railway_feature(source_id,name,kind,tags,geometry,source_as_of)
SELECT f->>'id',coalesce(f->'tags'->>'name:zh',f->'tags'->>'name','未命名铁路设施'), f->'tags'->>'railway',
       f->'tags',CASE WHEN f->'tags'->>'railway'='rail' THEN ST_SetSRID(ST_GeomFromGeoJSON((f->'geometry')::text),4326)
         ELSE ST_PointOnSurface(ST_SetSRID(ST_GeomFromGeoJSON((f->'geometry')::text),4326)) END,
       (f->>'sourceAsOf')::timestamptz
FROM dataset,LATERAL jsonb_array_elements(dataset.value->'features') f;
